package org.json; import java.util.*; public class JSONObject {private final Map<String,Object> fields=new HashMap<>();public JSONObject put(String k,Object v){fields.put(k,v);return this;}public JSONObject optJSONObject(String k){Object x=fields.get(k);return x instanceof JSONObject?(JSONObject)x:null;}public JSONArray optJSONArray(String k){Object x=fields.get(k);return x instanceof JSONArray?(JSONArray)x:null;}public String optString(String k){return optString(k,"");}public String optString(String k,String missing){Object x=fields.get(k);return x==null?missing:String.valueOf(x);}public int optInt(String k){Object x=fields.get(k);return x instanceof Number?((Number)x).intValue():0;}public long optLong(String k){Object x=fields.get(k);return x instanceof Number?((Number)x).longValue():0L;}}